1	// 隔离世界：① 注入 inject.js；② 转发接口响应(带当前店名)；③ 读流量待关注 chip；
2	// ④ 接收后台指令自动切店(轮巡用)。
3	(function () {
4	  const LOG = (...a) => { try { console.log('[TemuMon]', ...a); } catch (e) {} };
5	  const sleep = (ms) => new Promise((r) => setTimeout(r, ms));
6	  console.log('%c[TemuMon] content.js 已加载 —— 修下架漏报版 v6', 'color:#16a34a;font-weight:bold');
7	
8	  // 页面操作互斥锁：scanWatchList/scanOnSaleList/switchTo 都会改动「快速筛选/tab/切店」状态，
9	  // 绝不能并发——否则「商品流量待关注」筛选一打开，并发的在售扫描就只扫到筛选后的几条，
10	  // 误判成「下架 N 个」（这是历史假告警「在售 13→3」的根因）。所有改动型指令排队串行执行。
11	  let opChain = Promise.resolve();
12	  function withLock(fn) {
13	    const run = opChain.then(fn, fn); // 无论上一个成功/失败都接着跑（fn 不依赖上个结果）
14	    opChain = run.then(() => {}, () => {}); // 吞掉结果/异常，保持链条连续
15	    return run; // 调用方拿到 fn 的真实结果/异常
16	  }
17	
18	  // 注入 MAIN world hook
19	  try {
20	    const s = document.createElement('script');
21	    s.src = chrome.runtime.getURL('inject.js');
22	    s.onload = () => s.remove();
23	    (document.head || document.documentElement).appendChild(s);
24	  } catch (e) { /* ignore */ }
25	
26	  // ---------- 读当前店铺名（右上角英文店名） ----------
27	  function findStoreNameEl() {
28	    const W = window.innerWidth;
29	    let best = null;
30	    for (const el of document.querySelectorAll('span,a,div,button,p')) {
31	      const t = (el.textContent || '').trim();
32	      if (!/^[A-Za-z][A-Za-z0-9]*(?:\s[A-Za-z0-9]+){0,3}$/.test(t)) continue;
33	      if (t.length < 2 || t.length > 30) continue;
34	      if (/^(Seller Central|Beta|NEW|SKC|SKU|USD|Best Seller)$/i.test(t)) continue;
35	      // 排除纯大写+数字的货号/SKU（如 JMCATSZJ4）——真实店名都含小写字母
36	      if (/^[A-Z0-9]+$/.test(t)) continue;
37	      if (el.children.length > 2) continue;
38	      const r = el.getBoundingClientRect();
39	      if (r.width === 0 || r.top < 0 || r.top > 90) continue;
40	      if (r.left < W * 0.5) continue;
41	      if (!best || r.left > best.left) best = { el, left: r.left };
42	    }
43	    return best ? best.el : null;
44	  }
45	  function readStoreName() { const el = findStoreNameEl(); return el ? (el.textContent || '').trim() : null; }
46	
47	  // ---------- 转发接口响应 ----------
48	  window.addEventListener('message', (e) => {
49	    if (e.source !== window) return;
50	    const d = e.data;
51	    if (!d || d.__temuMon !== true) return;
52	    try { chrome.runtime.sendMessage({ type: 'capture', kind: d.kind, url: d.url, body: d.body, store: readStoreName() }); } catch (err) {}
53	  });
54	
55	  // ---------- 读流量异常 ----------
56	  // ①「商品流量待关注」是常驻的快速筛选 chip，实测 DOM（勿凭空改）：
57	  //     <div class="use-quick-field_tsx_card__HASH"><span>商品流量待关注</span>
58	  //       <span class="use-quick-field_tsx_countDistance__HASH">4</span></div>
59	  //   计数在独立的 countDistance span 里（chip 常驻，N=0 也在，只有 N 变大才是真异常）。
60	  // ②「商品流量近期有下降」不是 chip，是逐行红色徽标（见 countDeclineBadges）。
61	  // 关键坑：行内徽标「商品流量待关注 ›」嵌在价格 TD 里 → 价格单元格文本也含该标签。
62	  //   旧的"全页捞文本+最短优先"靠排序巧合才没读到价格数字；这里改为直接锚定 chip 容器。
63	  function readChipCount(all, label) {
64	    const re = new RegExp(label);
65	    // 精确路径：定位快速筛选 chip 容器（class 前缀 use-quick-field_tsx_card__ 稳定，
66	    // hash 后缀随构建变，用 *= 匹配前缀；card__ 带双下划线以免误匹配 cardBlock__）。
67	    for (const card of document.querySelectorAll('[class*="use-quick-field_tsx_card__"]')) {
68	      if (!re.test(card.textContent || '')) continue;
69	      const cnt = card.querySelector('[class*="countDistance"]');
70	      if (cnt && /\d/.test(cnt.textContent || '')) {
71	        return Number((cnt.textContent || '').replace(/[^\d]/g, ''));
72	      }
73	      const m = (card.textContent || '').match(new RegExp(label + '[^\\d]{0,3}([\\d,]+)'));
74	      if (m) return Number(m[1].replace(/,/g, ''));
75	    }
76	    // 兜底：chip class 若被改名，退回旧的全页文本匹配（最短优先 + 就近数字）
77	    const labels = all
78	      .filter((e) => re.test(e.textContent || '') && (e.textContent || '').trim().length < 24)
79	      .sort((a, b) => (a.textContent || '').length - (b.textContent || '').length);
80	    for (const el of labels) {
81	      for (const cand of [el, el.parentElement, el.parentElement && el.parentElement.parentElement]) {
82	        if (!cand) continue;
83	        const m = (cand.textContent || '').match(new RegExp(label + '[^\\d]{0,3}([\\d,]+)'));
84	        if (m) return Number(m[1].replace(/,/g, ''));
85	      }
86	      let sib = el.nextElementSibling;
87	      for (let i = 0; i < 3 && sib; i++, sib = sib.nextElementSibling) {
88	        const st = (sib.textContent || '').trim();
89	        if (/^[\d,]+$/.test(st)) return Number(st.replace(/,/g, ''));
90	      }
91	    }
92	    return null; // 读不到 → 未知（不当作 0，也不当作"有"）
93	  }
94	  // 「商品流量近期有下降」不是带计数的筛选 chip，而是逐行的红色徽标（列「商品优化事项」下）。
95	  // 因此按"当前页可见的行内徽标个数"来统计。注意：只覆盖当前页（默认 20 条/页），
96	  // 下降商品若在其它页则数不到——被动读数的固有限制，要精确总数得点筛选（主动模式）。
97	  function countDeclineBadges(all) {
98	    let n = 0;
99	    for (const e of all) {
100	      const t = (e.textContent || '').trim();
101	      if (!/商品流量近期有下降/.test(t) || t.length > 20) continue;
102	      // 只数最内层节点，避免父容器重复计数
103	      if ([...e.children].some((c) => /商品流量近期有下降/.test(c.textContent || ''))) continue;
104	      const r = e.getBoundingClientRect();
105	      if (r.width > 0 && r.height > 0) n++; // 只数真正渲染出来的行徽标，排除隐藏的筛选项/图例
106	    }
107	    return n;
108	  }
109	  // 扫描当前页商品行：按「SPU ID(=productId)」边界把行分组成商品，
110	  // 识别哪些商品带「商品流量待关注 / 商品流量近期有下降」徽标，取 productId + 商品名 + SKC。
111	  // 局限：只覆盖当前页(默认 20 条/页)，跨页的限流/下降商品扫不到——被动读的固有限制
112	  //（chip 计数 trafficWatch 才是全量总数；这里只为「点名 + 给编辑链接」）。
113	  function scanProducts() {
114	    const rows = [...document.querySelectorAll('[data-testid="beast-core-table-body-tr"]')];
115	    const products = [];
116	    let cur = null;
117	    for (const tr of rows) {
118	      const t = tr.textContent || '';
119	      const spu = t.match(/SPU\s*ID[:：]\s*(\d+)/); // DOM「SPU ID」= API/编辑页的 productId
120	      if (spu) {
121	        // 商品名只在「商品信息」那一格取（含 SPU ID 的 td），排除「标签：值」属性行，取最长一段。
122	        // （曾扫整行 → 第 3 条抓成隔壁「商品属性」列的「主体材质：铝合金」，故限定到该 td。）
123	        const infoTd = [...tr.querySelectorAll('td')].find((td) => /SPU\s*ID/.test(td.textContent || '')) || tr;
124	        const name = [...infoTd.querySelectorAll('*')].map((e) => (e.textContent || '').trim())
125	          .filter((x) => x.length >= 6 && x.length <= 80 && /[一-龥]/.test(x) && !/^.{0,6}[:：]/.test(x) && !/SPU|SKC/.test(x))
126	          .sort((a, b) => b.length - a.length)[0] || '';
127	        cur = { productId: spu[1], skc: (t.match(/SKC\s*ID[:：]\s*(\d+)/) || [])[1] || '', name: name, watch: false, decline: false };
128	        products.push(cur);
129	      }
130	      if (cur) {
131	        if (/商品流量待关注/.test(t)) cur.watch = true;
132	        if (/商品流量近期有下降/.test(t)) cur.decline = true;
133	      }
134	    }
135	    return products;
136	  }
137	  function readTraffic() {
138	    const all = [...document.querySelectorAll('*')];
139	    return {
140	      watch: readChipCount(all, '商品流量待关注'),
141	      decline: countDeclineBadges(all),
142	    };
143	  }
144	  const pickItem = (p) => ({ productId: p.productId, name: p.name, skc: p.skc });
145	  // 常驻轮询：每 2s 读一次 chip 计数 + 扫一次商品明细，但**只在结果变化时上报**
146	  //（靠 dedupe 避免刷爆后台）。这样用户后点「商品流量待关注」筛选/翻页时，
147	  // 明细也会在 2s 内自动刷新——旧版只在加载后 40s 内扫、之后点筛选就不扫了。
148	  let tries = 0;
149	  let lastKey = '';
150	  setInterval(() => {
151	    tries++;
152	    // 商品表格是否已渲染出行——徽标在行里，必须等行出来再扫，否则会在徽标出现前就读成空
153	    const gridReady = !!document.querySelector('[data-testid="beast-core-table-body-tr"]');
154	    const { watch, decline } = readTraffic();
155	    const msg = { type: 'chipStats', store: readStoreName() };
156	    if (watch != null) msg.trafficWatch = watch;
157	    let watchItems = [];
158	    let declineItems = [];
159	    if (gridReady) {
160	      const products = scanProducts();
161	      watchItems = products.filter((p) => p.watch).map(pickItem);
162	      declineItems = products.filter((p) => p.decline).map(pickItem);
163	      msg.trafficDecline = decline; // 仅在表格渲染后 decline 才可信
164	      msg.watchItems = watchItems;
165	      msg.declineItems = declineItems;
166	    }
167	    // 有 count 时等网格就绪再发（尽量带上明细）；网格长时间卡「加载中」(tries>8≈16s)时 count-only 兜底
168	    const readyOrTimedOut = gridReady || tries > 8;
169	    if (!((msg.trafficWatch != null && readyOrTimedOut) || 'trafficDecline' in msg)) return;
170	    // 结果没变化就不重发；变化了（如刚点了筛选、切了店）才上报
171	    const key = JSON.stringify([msg.store, msg.trafficWatch, msg.trafficDecline,
172	      watchItems.map((i) => i.productId), declineItems.map((i) => i.productId)]);
173	    if (key === lastKey) return;
174	    lastKey = key;
175	    try { chrome.runtime.sendMessage(msg); } catch (e) {}
176	  }, 2000);
177	
178	  // ---------- 切店自动化（轮巡用，由后台指令驱动） ----------
179	  async function waitFor(fn, timeout, step) {
180	    const t0 = Date.now();
181	    for (;;) { let r; try { r = fn(); } catch (e) { r = null; } if (r) return r; if (Date.now() - t0 > (timeout || 6000)) return null; await sleep(step || 200); }
182	  }
183	  function textEls(re, maxLen) {
184	    return [...document.querySelectorAll('*')].filter((e) => { const t = (e.textContent || '').trim(); return re.test(t) && t.length <= (maxLen || 40); });
185	  }
186	  function innermost(els) { return els.slice().sort((a, b) => (a.textContent || '').length - (b.textContent || '').length)[0] || null; }
187	  function clickableAncestor(el) { let n = el; for (let i = 0; i < 5 && n; i++) { if (n.tagName === 'BUTTON' || n.tagName === 'A' || n.getAttribute('role') === 'button') return n; n = n.parentElement; } return el; }
188	  // 完整鼠标事件序列（很多组件要 mousedown/up 才触发，单纯 click 不生效）
189	  function realClick(el) {
190	    if (!el) return false;
191	    const opts = { bubbles: true, cancelable: true, view: window };
192	    try { el.scrollIntoView({ block: 'center' }); } catch (e) {}
193	    for (const type of ['pointerdown', 'mousedown', 'mouseup', 'click']) {
194	      try { el.dispatchEvent(new MouseEvent(type, opts)); } catch (e) {}
195	    }
196	    try { el.click(); } catch (e) {}
197	    return true;
198	  }
199	  function modalOpen() { return textEls(/切换店铺|您的账户存在/, 20).length > 0; }
200	  function closeModal() {
201	    const x = document.querySelector('[aria-label="Close"],[aria-label="关闭"],.beast-core-modal-close,.semi-modal-close,.SnowModal_closeIcon');
202	    if (x) { realClick(x); return; }
203	    document.dispatchEvent(new KeyboardEvent('keydown', { key: 'Escape', keyCode: 27, bubbles: true }));
204	  }
205	
206	  // 压缩输出某元素的 HTML 骨架（去 style/data 属性），便于回传诊断
207	  function domSkel(el, maxLen) {
208	    if (!el) return 'null';
209	    let h = (el.outerHTML || '');
210	    h = h.replace(/\s(style|data-[\w-]+|aria-[\w-]+)="[^"]*"/g, '').replace(/>\s+</g, '><').replace(/\s{2,}/g, ' ');
211	    return h.slice(0, maxLen || 2200);
212	  }
213	
214	  function visible(el) { const b = el.getBoundingClientRect(); return b.width > 0 && b.height > 0; }
215	
216	  async function openStoreModal(diag) {
217	    diag = diag || [];
218	    if (modalOpen()) { diag.push('弹窗已开'); return true; }
219	    const nameEl = findStoreNameEl();
220	    diag.push('店名=' + (nameEl ? (nameEl.textContent || '').trim() : 'null'));
221	    if (nameEl) {
222	      // 只点一次触发下拉：点店名的可点祖先 + 店名右侧箭头坐标（避免多次点击把下拉又关掉）
223	      const r = nameEl.getBoundingClientRect();
224	      realClick(clickableAncestor(nameEl));
225	      const el = document.elementFromPoint(Math.min(window.innerWidth - 3, r.right + 14), r.top + r.height / 2);
226	      if (el && el !== nameEl) realClick(el);
227	    }
228	    // 下拉里“切换”按钮：只认可见的、精确文本“切换”，取最后一个（下拉通常在 DOM 靠后）
229	    const sw = await waitFor(() => {
230	      const cands = textEls(/^切换$/, 6).filter(visible);
231	      return cands.length ? clickableAncestor(cands[cands.length - 1]) : null;
232	    }, 3500);
233	    diag.push('下拉切换按钮=' + !!sw);
234	    if (sw) realClick(sw);
235	    const ok = !!(await waitFor(() => (modalOpen() ? true : null), 4500));
236	    diag.push('弹窗打开=' + ok);
237	    if (!ok) {
238	      const cands = textEls(/切换/, 8).map((e) => {
239	        const b = e.getBoundingClientRect();
240	        return e.tagName + '.' + String(e.className || '').split(' ')[0] + '[' + (e.textContent || '').trim().slice(0, 6) + ',y' + Math.round(b.top) + ',w' + Math.round(b.width) + ']';
241	      });
242	      diag.push('切换候选(' + cands.length + ')=' + cands.join(' '));
243	      diag.push('模态计数 切换店铺=' + textEls(/切换店铺/, 20).length + ' 您的账户=' + textEls(/您的账户/, 40).length);
244	    }
245	    return ok;
246	  }
247	
248	  async function listStores() {
249	    if (!(await openStoreModal())) return [];
250	    await sleep(500);
251	    // 每个店铺行都带“半托管/全托管”标签；据此定位店名，避开背景页面的杂项英文
252	    const tags = textEls(/托管/, 6).filter(visible);
253	    const names = [];
254	    for (const tag of tags) {
255	      let row = tag.parentElement;
256	      for (let i = 0; i < 4 && row; i++) {
257	        const en = [...row.querySelectorAll('span,div,p,a')]
258	          .map((e) => (e.textContent || '').trim())
259	          .find((t) => /^[A-Za-z][A-Za-z0-9]*(?:\s[A-Za-z0-9]+){0,3}$/.test(t) && t.length >= 2 && t.length <= 30 && !/^(NEW|Beta)$/i.test(t));
260	        if (en) { names.push(en); break; }
261	        row = row.parentElement;
262	      }
263	    }
264	    closeModal();
265	    const uniq = [...new Set(names)];
266	    LOG('listStores =>', uniq);
267	    return uniq;
268	  }
269	
270	  async function switchTo(target) {
271	    const diag = [];
272	    if (!(await openStoreModal(diag))) return { ok: false, msg: '打不开弹窗 | ' + diag.join(' ; ') };
273	    await sleep(300);
274	    const esc = String(target).replace(/[.*+?^${}()|[\]\\]/g, '\\$&');
275	    const rows = textEls(new RegExp(esc), 120).filter((e) => /切换/.test(e.textContent || ''));
276	    const row = innermost(rows);
277	    if (!row) { closeModal(); return { ok: false, msg: '弹窗里没找到店铺 ' + target }; }
278	    let btn = [...row.querySelectorAll('button,[role=button]')].find((b) => /切换/.test(b.textContent || '') && !b.disabled && b.getAttribute('aria-disabled') !== 'true');
279	    if (!btn) {
280	      const cands = textEls(/^切换$/, 6).map(clickableAncestor).filter((b) => b && !b.disabled);
281	      btn = cands.find((b) => row.contains(b) || (b.compareDocumentPosition(row) & Node.DOCUMENT_POSITION_CONTAINED_BY)) || null;
282	    }
283	    if (!btn) { closeModal(); return { ok: false, msg: '没找到可点的切换按钮(' + target + ')，可能已是当前店' }; }
284	    LOG('switchTo click', target);
285	    realClick(btn); // 触发切店（SPA 更新或整页重载）
286	    return { ok: true, msg: '已点击切换到 ' + target };
287	  }
288	
289	  // ---------- 主动捞「商品流量待关注」明细（发现异常时调，点筛选→扫→重置） ----------
290	  // 读列表底部「共有 N 条」（筛选生效后该数=待关注总数）
291	  function readTotalCount() {
292	    const el = [...document.querySelectorAll('*')].find(
293	      (x) => x.children.length === 0 && /共有\s*[\d,]+\s*条/.test(x.textContent || '')
294	    );
295	    if (!el) return null;
296	    const m = (el.textContent || '').match(/共有\s*([\d,]+)\s*条/);
297	    return m ? Number(m[1].replace(/,/g, '')) : null;
298	  }
299	  // 定位「商品流量待关注」快速筛选 chip 容器（与 readChipCount 同一稳定 class 前缀）
300	  function findWatchChip() {
301	    for (const card of document.querySelectorAll('[class*="use-quick-field_tsx_card__"]')) {
302	      if (/商品流量待关注/.test(card.textContent || '')) return card;
303	    }
304	    return null;
305	  }
306	  // 点「重置」清掉快速筛选，恢复用户视图
307	  function clickReset() {
308	    const btn = textEls(/^重置$/, 6).filter(visible)[0];
309	    if (btn) realClick(clickableAncestor(btn));
310	  }
311	  // 点开「商品流量待关注」筛选 → 扫出这几条商品(productId+name+skc) → 重置。
312	  // 筛选生效后网格里每行都是待关注商品，故取全部行（不再依赖行内徽标）。
313	  // 只覆盖筛选后的当前页(默认 20 条)，>20 条的溢出由 total 提示行说明。
314	  async function scanWatchList() {
315	    const chip = findWatchChip();
316	    if (!chip) return { store: readStoreName(), items: [], applied: false, msg: '未找到待关注筛选 chip' };
317	    const before = readTotalCount();
318	    realClick(clickableAncestor(chip));
319	    // 等列表真正刷新：底部「共有 N 条」的数值发生变化（通常变小）才算筛选生效
320	    await waitFor(() => {
321	      const t = readTotalCount();
322	      return (t != null && before != null && t !== before) ? t : null;
323	    }, 8000, 300);
324	    await sleep(1200); // 等筛选后的网格稳定渲染
325	    const after = readTotalCount();
326	    // 仅当确实生效（数值变化且不大于原总数）才采纳，绝不把未筛选的整页当成待关注
327	    const applied = after != null && before != null && after !== before && after <= before;
328	    let items = [];
329	    if (applied) items = scanProducts().map((p) => ({ productId: p.productId, name: p.name, skc: p.skc }));
330	    // 复位（必须彻底清掉筛选，否则会污染随后的在售扫描 → 误报下架）：
331	    //   ① 若已生效，再点一次同一 chip toggle 回未选中（比只点「重置」更精准可靠）；
332	    //   ② 再点「重置」兜底；③ 等「共有 N 条」回升到筛选前的值，确认筛选真的清掉了。
333	    if (applied) realClick(clickableAncestor(chip));
334	    clickReset();
335	    await waitFor(() => {
336	      const t = readTotalCount();
337	      return (t != null && before != null && t >= before) ? t : null;
338	    }, 6000, 300);
339	    await sleep(600);
340	    return { store: readStoreName(), items: items, total: after, applied: applied };
341	  }
342	
343	  // 读某个 tab 标签上印的数字（形如「在售中 13」/「全部 214」）。干净无筛选视图下=真实数量。
344	  function readTabCount(re) {
345	    const labels = [...document.querySelectorAll('[data-testid="beast-core-tab-itemLabel"]')].filter(visible);
346	    for (const el of labels) {
347	      const t = (el.textContent || '').trim();
348	      if (re.test(t)) { const m = t.match(/(\d[\d,]*)/); if (m) return Number(m[1].replace(/,/g, '')); }
349	    }
350	    return null;
351	  }
352	  // 扫「在售中」商品清单：先复位到干净视图 → 点在售 tab → 等在售网格 → scanProducts 取 productId+name+skc。
353	  // 用于 background diff 出"上轮在售、这轮不在"的下架商品。仅轮巡(空闲)时调，扫完点回「全部」。
354	  // ⚠️ 关键：扫描前**必须**清掉一切快速筛选（尤其「商品流量待关注」）——否则会只扫到筛选后的
355	  //    几条在售商品，误报「下架 N 个」（历史假告警根因）。这里主动复位，不依赖调用时机的干净。
356	  async function scanOnSaleList() {
357	    const findTab = (re) => {
358	      const labels = [...document.querySelectorAll('[data-testid="beast-core-tab-itemLabel"]')].filter(visible);
359	      return labels.find((e) => re.test((e.textContent || '').trim())) || textEls(re, 14).filter(visible)[0] || null;
360	    };
361	    // ① 复位到干净、无快速筛选的状态：先回「全部」tab，再点「重置」清掉任何快速筛选 chip。
362	    const allTab0 = findTab(/^全部/);
363	    if (allTab0) realClick(clickableAncestor(allTab0));
364	    await sleep(300);
365	    clickReset();
366	    await sleep(1000);
367	    // ② 点「在售中」tab，等网格渲染
368	    const onSaleTab = findTab(/^在售中/);
369	    if (onSaleTab) realClick(clickableAncestor(onSaleTab));
370	    await waitFor(() => document.querySelector('[data-testid="beast-core-table-body-tr"]'), 8000, 300);
371	    await sleep(1800); // 等在售网格稳定渲染（避免只扫到半页）
372	    // ③ 读干净视图下「在售中 N」的真实数字——作为 background 判定"是否扫全/是否被筛选污染"的权威值
373	    const onSaleTabCount = readTabCount(/^在售中/);
374	    const products = scanProducts();
375	    const items = products.map((p) => ({ productId: p.productId, name: p.name, skc: p.skc }));
376	    LOG('scanOnSale', 'tabCount=' + onSaleTabCount, 'scanned=' + items.length,
377	      items.length && onSaleTabCount && items.length < onSaleTabCount ? '⚠ 可能分页截断' : '');
378	    // 恢复到「全部」tab（轮巡时用户看不到，但保持视图干净）
379	    const allTab = findTab(/^全部/);
380	    if (allTab) realClick(clickableAncestor(allTab));
381	    return { store: readStoreName(), items: items, onSaleTabCount: onSaleTabCount };
382	  }
383	
384	  chrome.runtime.onMessage.addListener((msg, sender, sendResponse) => {
385	    if (!msg || !msg.cmd) return;
386	    (async () => {
387	      try {
388	        if (msg.cmd === 'ping') { sendResponse({ store: readStoreName() }); return; } // 只读，不入锁
389	        if (msg.cmd === 'listStores') { sendResponse({ names: await withLock(listStores) }); return; }
390	        if (msg.cmd === 'switchTo') { sendResponse(await withLock(() => switchTo(msg.target))); return; }
391	        if (msg.cmd === 'scanOnSale') { sendResponse(await withLock(scanOnSaleList)); return; }
392	        if (msg.cmd === 'scanWatchList') { sendResponse(await withLock(scanWatchList)); return; }
393	      } catch (e) { sendResponse({ ok: false, msg: String((e && e.message) || e) }); }
394	    })();
395	    return true;
