5	  return String(s).replace(/[&<>"']/g, (c) => ({ '&': '&amp;', '<': '&lt;', '>': '&gt;', '"': '&quot;', "'": '&#39;' }[c]));
6	}
7	function setMsg(text, cls) {
8	  const el = document.getElementById('msg');
9	  el.textContent = text || '';
10	  el.className = cls || '';
11	}
