async function refresh() {
  const s = await send('getStatus');
  const cfg = (s && s.config) || {};
  const stores = (s && s.stores) || {};

  document.getElementById('cfg').textContent =
    '飞书：' + (cfg.webhook ? (cfg.enabled ? '已启用' : '已停用') : '未配置')
