// logger.js - Shared structured logging for Temu plugin
// Works in: service worker, content script, popup
// Context detection: typeof window === 'undefined' → service worker

(function() {
  const MAX_ENTRIES = 500;
  const STORAGE_KEY = 'logs';

  function fmtTs() {
    const d = new Date();
    const pad = (n) => String(n).padStart(2, '0');
    return d.getFullYear() + '-' + pad(d.getMonth() + 1) + '-' + pad(d.getDate()) +
      ' ' + pad(d.getHours()) + ':' + pad(d.getMinutes()) + ':' + pad(d.getSeconds());
  }

  function isServiceWorker() {
    return typeof window === 'undefined' && typeof self !== 'undefined' && typeof importScripts === 'function';
  }

  // Direct storage write (used by service worker)
  async function writeToStorage(entry) {
    try {
      const result = await chrome.storage.local.get(STORAGE_KEY);
      const logs = result[STORAGE_KEY] || [];
      logs.push(entry);
      // Ring buffer: keep only last MAX_ENTRIES
      if (logs.length > MAX_ENTRIES) {
        logs.splice(0, logs.length - MAX_ENTRIES);
      }
      await chrome.storage.local.set({ [STORAGE_KEY]: logs });
    } catch (e) { /* silently fail */ }
  }

  // Send to background (used by content script / popup)
  function sendToBackground(entry) {
    try {
      chrome.runtime.sendMessage({ type: 'log', entry: entry }, function() {
        // Ignore response; chrome.runtime.lastError is expected if no listener
        if (chrome.runtime.lastError) { /* silently ignore */ }
      });
    } catch (e) { /* silently ignore */ }
  }

  function createLogger(name) {
    function log(level, msg) {
      var entry = { ts: fmtTs(), level: level, msg: String(msg) };
      // Console output (all contexts)
      var prefix = '[' + entry.ts + '] [' + level + ']';
      try {
        switch (level) {
          case 'ERROR': console.error(prefix, msg); break;
          case 'WARN': console.warn(prefix, msg); break;
          default: console.log(prefix, msg); break;
        }
      } catch (e) {}

      // Persistent storage
      if (isServiceWorker()) {
        writeToStorage(entry);
      } else {
        sendToBackground(entry);
      }
    }

    return {
      info: function(msg) { log('INFO', msg); },
      warn: function(msg) { log('WARN', msg); },
      error: function(msg) { log('ERROR', msg); }
    };
  }

  // Export
  if (typeof window !== 'undefined') {
    window.TemuLogger = { createLogger: createLogger };
  } else {
    self.TemuLogger = { createLogger: createLogger };
  }
})();
```

