      html += '<div style="color:' + color + '">[' + esc(e.ts) + '] [' + esc(e.level) + '] ' + msg + '</div>';
    }
    if (!recent.length) {
      html = '<div style="color:#8a9099">（暂无日志）</div>';
    }
    listEl.innerHTML = html;
    // Auto-scroll to top (newest)
    if (logVisible) listEl.scrollTop = 0;
  });
}

function toggleLogs() {
