      text += '[' + logs[i].ts + '] [' + logs[i].level + '] ' + logs[i].msg + '\n';
    }
    if (!text) text = '(no logs)\n';
    var blob = new Blob([text], { type: 'text/plain;charset=utf-8' });
    var url = URL.createObjectURL(blob);
    var a = document.createElement('a');
    a.href = url;
    a.download = 'temu-monitor-' + new Date().toISOString().slice(0, 10) + '.log';
    a.click();
    URL.revokeObjectURL(url);
    LOG.info('Logs exported: ' + logs.length + ' entries');
  });
}
```

#### 6.3 Wire Up Event Listeners

Add at the end of the existing script (after `refresh();` on line 109):

```javascript
document.getElementById('logToggle').addEventListener('click', toggleLogs);
document.getElementById('logExport').addEventListener('click', exportLogs);
```

#### 6.4 Reuse Existing `esc()` Function

The existing `esc()` function on line 4 of popup.js handles `&<>"'` but not all characters. For log messages it is adequate. The log rendering code already performs `replace()` for `&`, `<`, `>` and then passes through `esc()` for the timestamp and level (which are generated by our own code and inherently safe, but `esc()` is an extra safety measure). Actually, `esc()` converts `&` to `&amp;`, but we already did `&amp;` replacement on msg. To avoid double-escaping, either:
- Do NOT use `esc()` on msg (since we already did manual escaping), OR
- Use `esc()` on the raw msg and skip manual escaping

The simplest approach: use `esc()` on everything consistently, and skip the manual replacements. Replace the msg escaping with:

```javascript
var msg = esc(String(e.msg));
```

And keep `esc(e.ts)` and `esc(e.level)` as they are.

#### 6.5 Cleanup on Popup Close

The `setInterval` for auto-refresh should be cleaned up when the popup closes. However, in a Chrome extension popup, the entire window context is destroyed when the popup closes, so the interval is automatically garbage-collected. No explicit cleanup is required. If we wanted to be extra careful, we could add:

```javascript
window.addEventListener('unload', function () {
  if (logTimer) clearInterval(logTimer);
});
```

But this is unnecessary given the popup's lifecycle. Omitting it keeps the code simpler.

